type CopyToClipboardState = {
  status: "idle" | "copied" | "error";
  revision: number;
  isCopied: boolean;
  isPending: boolean;
  error: unknown;
};
type CopyToClipboardOptions = {
  timeout?: number;
  onCopy?: () => void;
  onError?: (error: unknown) => void;
};
type CopyToClipboardValue = string | (() => Promise<string>);
const idleState: CopyToClipboardState = {
  status: "idle",
  revision: 0,
  isCopied: false,
  isPending: false,
  error: null,
};

/** Framework-independent clipboard lifecycle. Dispose when the owner unmounts. */
function createCopyToClipboard() {
  let state = idleState;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let generation = 0;
  const listeners = new Set<() => void>();
  const update = (next: CopyToClipboardState) => {
    state = next;
    for (const listener of listeners) listener();
  };
  return {
    getSnapshot: () => state,
    getServerSnapshot: () => idleState,
    subscribe(this: void, listener: () => void) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    async copyToClipboard(
      value: CopyToClipboardValue,
      { timeout = 2000, onCopy, onError }: CopyToClipboardOptions = {},
    ): Promise<boolean> {
      if (state.isPending) return false;
      const operation = ++generation;
      clearTimeout(timer);
      update({ ...state, isPending: true });
      try {
        if (typeof navigator === "undefined" || !navigator.clipboard?.writeText) {
          throw new Error("Clipboard access is unavailable");
        }
        const text = typeof value === "function" ? await value() : value;
        if (operation !== generation) return false;
        await navigator.clipboard.writeText(text);
      } catch (error) {
        if (operation === generation) {
          update({
            status: "error",
            revision: state.revision + 1,
            isCopied: false,
            isPending: false,
            error,
          });
          if (timeout !== 0)
            timer = setTimeout(() => {
              if (generation === operation) update({ ...idleState, revision: state.revision });
            }, timeout);
          onError?.(error);
        }
        return false;
      }
      if (operation !== generation) return true;
      update({
        status: "copied",
        revision: state.revision + 1,
        isCopied: true,
        isPending: false,
        error: null,
      });
      if (timeout !== 0)
        timer = setTimeout(() => {
          if (generation === operation) update({ ...idleState, revision: state.revision });
        }, timeout);
      onCopy?.();
      return true;
    },
    reset(this: void) {
      generation++;
      clearTimeout(timer);
      update({ ...idleState, revision: state.revision });
    },
    dispose() {
      generation++;
      clearTimeout(timer);
      state = idleState;
    },
  };
}
export { createCopyToClipboard };
export type { CopyToClipboardOptions, CopyToClipboardState, CopyToClipboardValue };
